document.querySelector("#batch36 .grid").insertAdjacentHTML("beforeend","<a class=\"card\" href=\"summaries/paranormal-28.html\"><div class=\"book-art real-cover\"><img alt=\"غلاف أسطورة آخر الليل : سلسلة ما وراء الطبيعة 28\" height=\"360\" loading=\"lazy\" src=\"data:image/webp;base64,\" width=\"270\"/></div><span class=\"tag\">روايات وغموض · مرجع تجاري</span><h3>أسطورة آخر الليل : سلسلة ما وراء الطبيعة 28</h3><p>المقتطف المنشور يقدم رفعت إسماعيل نفسه مرة أخرى، مع التفاتة إلى من يجلسون إلى مائدته للمرة الأولى. يربط هذا الأسلوب العدد بقارئ قديم يعرف الصوت وقارئ جديد …</p><small>أحمد خالد توفيق · مدخل موثق وأسئلة قراءة</small></a><a class=\"card\" href=\"summaries/paranormal-29.html\"><div class=\"book-art real-cover\"><img alt=\"غلاف أسطورة الجاثوم: سلسلة ما وراء الطبيعة 29\" height=\"360\" loading=\"lazy\" src=\"data:image/webp;base64,\" width=\"270\"/></div><span class=\"tag\">روايات وغموض · مرجع تجاري</span><h3>أسطورة الجاثوم: سلسلة ما وراء الطبيعة 29</h3><p>تربط النبذة الجاثوم بنداء يعبر الأجيال وبكوابيس وقصر واسع مظلم ووحدة أمام كيان مخيف. هذا تركيب تخييلي عن الخوف الممتد، لا شرح طبي لشلل النوم ولا إثبات لاتص…</p><small>أحمد خالد توفيق · مدخل موثق وأسئلة قراءة</small></a><a class=\"card\" href=\"summaries/paranormal-30.html\"><div class=\"book-art real-cover\"><img alt=\"غلاف أسطورة بعد منتصف الليل: سلسلة ما وراء الطبيعة 30 - عدد خاص\" height=\"360\" loading=\"lazy\" src=\"data:image/webp;base64,\" width=\"270\"/></div><span class=\"tag\">روايات وغموض · مرجع تجاري</span><h3>أسطورة بعد منتصف الليل: سلسلة ما وراء الطبيعة 30 - عدد خاص</h3><p>هذا عدد خاص يقدم نفسه كنداء لمن يرى تحولا غريبا في صديق أو ضوءا في بيت مهجور أو وجها مختلفا في المرآة. تعدد الأمثلة يصنع عالما تتسرب فيه المفارقة إلى البيت…</p><small>أحمد خالد توفيق · مدخل موثق وأسئلة قراءة</small></a>");
